-- Políticas de storage.objects para los buckets de Compensaciones.
DROP POLICY IF EXISTS compensaciones_tarjetas_delete_orphan ON storage.objects;
CREATE POLICY compensaciones_tarjetas_delete_orphan ON storage.objects FOR DELETE TO authenticated
    USING (((bucket_id = 'compensaciones-tarjetas-erroneas'::text) AND f_private_compensacion_tarjeta_storage('ELIMINAR_HUERFANO'::text, name)));
DROP POLICY IF EXISTS compensaciones_tarjetas_insert ON storage.objects;
CREATE POLICY compensaciones_tarjetas_insert ON storage.objects FOR INSERT TO authenticated
    WITH CHECK (((bucket_id = 'compensaciones-tarjetas-erroneas'::text) AND f_private_compensacion_tarjeta_storage('SUBIR'::text, name)));
DROP POLICY IF EXISTS compensaciones_tarjetas_select ON storage.objects;
CREATE POLICY compensaciones_tarjetas_select ON storage.objects FOR SELECT TO authenticated
    USING (((bucket_id = 'compensaciones-tarjetas-erroneas'::text) AND f_private_compensacion_tarjeta_storage('LEER'::text, name)));
DROP POLICY IF EXISTS compensaciones_tiktok_delete_orphan ON storage.objects;
CREATE POLICY compensaciones_tiktok_delete_orphan ON storage.objects FOR DELETE TO authenticated
    USING (((bucket_id = 'compensaciones-tiktok-live'::text) AND f_private_compensacion_tiktok_storage('ELIMINAR_HUERFANO'::character varying, name)));
DROP POLICY IF EXISTS compensaciones_tiktok_insert ON storage.objects;
CREATE POLICY compensaciones_tiktok_insert ON storage.objects FOR INSERT TO authenticated
    WITH CHECK (((bucket_id = 'compensaciones-tiktok-live'::text) AND f_private_compensacion_tiktok_storage('SUBIR'::character varying, name)));
DROP POLICY IF EXISTS compensaciones_tiktok_select ON storage.objects;
CREATE POLICY compensaciones_tiktok_select ON storage.objects FOR SELECT TO authenticated
    USING (((bucket_id = 'compensaciones-tiktok-live'::text) AND f_private_compensacion_tiktok_storage('LEER'::character varying, name)));

